"Er reist mit leichtem Gepäck.","Bei schönem Wetter fahren wir Rad.","Ich bin für eine schnellere Entscheidung.","Das ist die schnellste Verbindung.","Er kommt später als erwartet.","Sie ist so groß wie ihr Bruder.","Er weiß mehr, als er sagt.","Ich frage mich, ob er kommt.","Ich glaube, dass er recht hat.","Das Buch, das dort liegt, ist neu.","Sie wusste, dass das nicht stimmt.","Er ist nach Hause gegangen.","Ich habe ihm das gegeben.","Er hat sich das anders vorgestellt.","Du sollst dich beeilen.","Ihr müsst euch entscheiden.","Wir können uns darauf verlassen.","Das Ich ist ein philosophischer Begriff.","Mit dem Du beginnt eine engere Beziehung.","Das Essen ist fertig.","Zum Lesen brauche ich Ruhe.","Beim Lernen hilft mir Musik.","Die automatisch geänderte Datei ist neu.","Der öffentlich geprüfte Bericht ist vollständig.","Die endgültig geschlossene Tür bleibt zu.","Eine leicht beschädigte Tür wird ersetzt.","Ein vollständig geänderter Text liegt vor.","Ein einfach schönes Haus steht dort.","Die Lage war früher wie heute schwierig.","Er war früher wie ein Bruder für mich.","Sie sah später wie ihre Mutter aus.","Das bleibt früher wie heute wichtig.","Ich komme später wie vereinbart.","Er ist schneller wie auch zuverlässiger geworden.","Das sind meine neuen Bücher.","Mit den neuen Bücherregalen ist alles gut.","Er hilft mit, die neuen Bücher zu tragen.","Ohne ihm helfen zu können, geht sie.","Um dem Mann zu helfen, bleibt sie.","Um des Mannes willen bleibt sie.","Das ist mit ein wichtiger Satz.","Seit ich hier bin, läuft es besser.","Er stellt sich so klein als möglich dar.","Ohne ihm böse zu sein, geht sie.","Ohne mir weh zu tun, hilft er.","Um ihm nahe zu sein, bleibt sie.","Um mir einen Gefallen zu tun, kommt er.","Ohne dem Kind weh zu tun, löst sie das Pflaster.","Mit den Autos fahren wir zur Schule.","Für die Autos brauchen wir neue Reifen.","Mit den Büros ist sie zufrieden.","Mit den Computern arbeiten wir jeden Tag.","Mit den Ferien beginnt eine schöne Zeit.","Mit den Eltern spricht er morgen.","Mit den Daten können wir arbeiten.","Mit dem Jungen spricht sie über das Projekt.","Für den Herrn ist das Buch bestimmt.","Bei dem Kollegen liegt die Datei.","Mit dem Menschen hat sie nichts zu tun.","Für den Studenten ist die Aufgabe leicht.","Wir fragen den Präsidenten nach seiner Meinung.","Für Sie ist ein Zimmer reserviert.","Mit Ihnen würden wir gern sprechen.","Ich schicke Ihnen den Bericht.","Gegenüber Ihnen verhält er sich höflich.","Seit sie hier arbeitet, ist sie zufrieden.","Seit Sie hier arbeiten, ist alles besser.","Wir sprechen mit Frau Müller.","Die Datei gehört Herrn Müller.","Mit meinem Freund Hans besuche ich das Haus.","Für den Zeugen Herrn Müller ist das wichtig.","Beim Schreiben denke ich nach.","Zum Lesen fehlt mir die Zeit.","Mit dem Neuen ist alles gut.","Mit etwas Neuem fängt man an.","Mit den Deutschen sprechen wir Englisch.","Für die Deutschen ist das eine neue Regel.","Für das Gute kämpfen wir gemeinsam.","Ich glaube das. Er kommt später.","Ich glaube, das ist richtig.","Ich weiß das, er hat es mir gesagt.","Ich glaube, dass er kommt; du gehst.","Ich glaube „das“, er glaubt „dies“.","Ich glaube `das er kommt` ist Code.","Ich weiß, dass er https://example.de/mit/den/Kindern besucht.","Die Datei `mit den Kinder` enthält Text.","Sie sagt „mit den Kindern“ und bleibt.","Ich glaube das\nEr kommt später.","Um den Mann herum steht eine Gruppe.","Um des Kindes willen bleibt sie hier.","Das passiert ganz ohne mich.","Sie ist ohne ihn nicht glücklich.","Sie fährt für ihn nach Hause.","Von diesem Tage an blieb er zuhause.","Nach dem Jahre 1990 änderte sich vieles.","Aus dem Texte geht es hervor.","Mit dem Tage beginnt ein neues Leben.","Ohne mir angesichts der mehrfachen Schwierigkeiten und der vielen unvorhersehbaren technischen Hindernisse in diesem besonders anspruchsvollen und langwierigen Projekt aus früheren Jahren helfen zu können, geht sie.","Um dem Kind nach diesem sehr langen und anstrengenden Tag voller ungewöhnlicher und überraschender Ereignisse im kleinen Haus am Rande der Stadt schließlich doch noch zu helfen, bleibt sie.","Man nehme zwei Eier.","Er habe keine Zeit, sagte sie.","Sie sagt, er komme morgen.","Man gehe vorsichtig vor.","Er werde den Auftrag erfüllen.","Er sei krank.","Er könne nicht kommen.","Er müsse gehen.","Man halte Abstand.","Man gebe etwas Wasser hinzu.","Man esse langsam.","Habe du nur Geduld!","Lerne du erst einmal Deutsch!","Gehe du nach Hause!","Mache du das!","Arbeite du heute hier!","Geht ihr schon?","Kann ihr Bruder das?","Was gibt ihr Hoffnung?","Ich gebe ihr das Buch.","Er sagt ihr nichts.","Ich sehe ihr Auto.","Liegt ihr Bericht hier?","Das wird ihr helfen.","Ist ihr kalt?","Kann ich gehen?","Kannst du warten?","Wir können gehen.","Ich werde kommen.","Wenn er komme, solle sie warten.","Er konnte nicht kommen.","Gehe ich recht in der Annahme?","Gehen wir beide?","Gehen wir und unsere Kinder gemeinsam?","Gehen ich und mein Bruder gemeinsam?","Gehen er und seine Frau gemeinsam?","Haben du und ich Zeit?","Dass ich gehe, überrascht sie nicht.","Weil ich Essen koche, bleibe ich hier.","Ich lasse ihn gehen.","Er lässt mich gehen.","Er hat sich schlafen gelegt.","Ich kann mich sehen.","Geht’s dir gut?","Seien Sie ruhig!","Gib mir das Buch.","Machst du das?","Haben Ich und Du ihre Bedeutung verloren?","Das Du kann Nähe ausdrücken.","Das Ich hat seine Grenzen.","Er plant `ich gehen` als Test.","Er geht.\nIch gehe.","Das Formular enthält die Wörter „er“ und „gehen“.","Ein leise geschlossenes Fenster hilft dem Kind.","Mit dem leise geschlossenen Fenster ist es ruhig.","Ein müde geprüfter Bericht liegt vor.","Könnte ich gehen?","Würde ich gehen?","Möchte ich helfen?","Sollte ich warten?","Dürfte ich kommen?","Wollte ich bleiben?","Auf Man leben viele Menschen.","Die Insel Man haben wir besucht.","Weil ich schlafen möchte, gehe ich nach Hause.","Wenn er essen geht, wartet sie."]}';

Future<void> main() async {
  final data = jsonDecode(fixtures) as Map<String, dynamic>;
  final positive = (data['positive'] as List).cast<Map<String, dynamic>>();
  final negative = (data['negative'] as List).cast<String>();
  final provider = GermanWritingRulesProvider();
  final failures = <Map<String, Object?>>[];
  var requests = 0;
  var correctionRechecks = 0;
  var variants = 0;
  Future<OfficeProofingResult> check(String text, {int offset = 0, String language = 'de-DE', Set<String> ignored = const {}}) async {
    requests++;
    final result = await provider.check(OfficeProofingRequest(documentId: 'independent-grammar-review', blockId: 'case', revision: requests,
      text: text, startOffset: offset, language: language, ignoredRuleIds: ignored));
    if (result.status != OfficeProofingStatus.success) failures.add({'stage': 'provider-status', 'text': text, 'detail': result.status.name, 'message': result.message});
    return result;
  }
  void fail(String stage, String text, Object? detail) => failures.add({'stage': stage, 'text': text, 'detail': detail});
  for (final fixture in positive) {
    final text = fixture['text'] as String;
    final rule = fixture['rule'] as String;
    final original = fixture['original'] as String;
    final replacement = fixture['replacement'] as String;
    for (final variant in ['base', 'offset', 'soft-hyphen']) {
      variants++;
      var source = text;
      var expectedOriginal = original;
      if (variant == 'soft-hyphen') {
        final insertAt = original.isEmpty ? 1 : source.indexOf(original) + 1;
        source = source.replaceRange(insertAt, insertAt, '\u00ad');
        if (original.isNotEmpty) expectedOriginal = original.replaceRange(1, 1, '\u00ad');
      }
      final offset = variant == 'base' ? 0 : 37;
      if (offset != 0) source = '🙂 $source';
      final expectedReplacement = variant == 'soft-hyphen' ? replacement.replaceAll('ß', 'ss') : replacement;
      final variantLanguage = variant == 'base' ? 'de-DE' : variant == 'offset' ? 'de-AT' : 'de-CH';
      final result = await check(source, offset: offset, language: variantLanguage);
      final findings = result.findings;
      if (findings.length != 1) {
        fail(variant, source, {'expectedRule': rule, 'actualRules': findings.map((f) => f.ruleId).toList()});
        continue;
      }
      final finding = findings.single;
      if (finding.ruleId != rule || finding.originalText != expectedOriginal || finding.replacements.length != 1 || finding.replacements.single != expectedReplacement) {
        fail(variant, source, {'expectedRule': rule, 'expectedOriginal': expectedOriginal, 'expectedReplacement': expectedReplacement,
          'actualRule': finding.ruleId, 'actualOriginal': finding.originalText, 'actualReplacements': finding.replacements});
        continue;
      }
      final start = finding.start - offset;
      final end = finding.end - offset;
      if (start < 0 || end > source.length || source.substring(start, end) != expectedOriginal) {
        fail('source-range', source, {'start': start, 'end': end, 'expectedOriginal': expectedOriginal});
        continue;
      }
      final corrected = source.replaceRange(start, end, expectedReplacement);
      correctionRechecks++;
      final rechecked = await check(corrected, offset: offset, language: variantLanguage);
      if (rechecked.findings.isNotEmpty) fail('correction-recheck', corrected, rechecked.findings.map((f) => f.ruleId).toList());
    }
    variants++;
    final ignored = await check(text, ignored: {rule});
    if (ignored.findings.isNotEmpty) fail('ignore-rule', text, ignored.findings.map((f) => f.ruleId).toList());
    variants++;
    final protected = await check('🙂 `$text`', offset: 37);
    if (protected.findings.isNotEmpty) fail('protected-code', text, protected.findings.map((f) => f.ruleId).toList());
  }
  for (final text in negative) {
    final result = await check('🙂 $text', offset: 37);
    if (result.findings.isNotEmpty) fail('negative-control', text, [for (final f in result.findings) {'rule': f.ruleId, 'source': f.originalText, 'replacements': f.replacements}]);
  }
  await provider.dispose();
  print(const JsonEncoder.withIndent('  ').convert({'status': failures.isEmpty ? 'passed' : 'failed',
    'positive_sentences': positive.length, 'negative_sentences': negative.length, 'positive_variants': variants,
    'correction_rechecks': correctionRechecks, 'requests': requests, 'failures': failures,
    'scope': 'First-party independent behavioral cases; variants and rechecks are not separate language examples.'}));
  if (failures.isNotEmpty) throw StateError('Independent grammar review failed');
}
